+            CountDownLatch ready = new CountDownLatch(1);
+            CountDownLatch finish = new CountDownLatch(1);
+            AtomicReference<Throwable> error = new AtomicReference<>();
+
+            Thread vt = Thread.ofVirtual().name("RequestStackTrace-VThread").start(() -> {
+                try {
+                    ready.countDown();
+                    finish.await();
